    if "claims" not in data:
        raise ValidationError("缺少字段: claims")
    if not isinstance(data["claims"], dict):
        raise ValidationError("字段 claims 必须为 JSON 对象")
    # expires_at 可选：提供时必须为 UTC 秒精度 Z 格式且严格晚于
