    has_schema_id = "schema_id" in data
    has_schema_version = "schema_version" in data
    if has_schema_id != has_schema_version:
        raise ValidationError(
            "schema_id 与 schema_version 必须同时出现或同时省略"
        )
    try:
        record = store.create_credential(
            tenant,
            data["issuer_did"],
            data["subject_did"],
            data["claims"],
