        self._send_json(
            409, {"error": "credential schema unavailable"}
        )
        return
    self._send_json(
        201,
        {
            "credential_id": record.credential_id,
            "signature": record.signature,
            "issuer_key_version": record.body["issuer_key_version"],
        },
    )

